import random
import itertools
from collections import defaultdict

def check_girth(edges, n, min_girth=7):
    """Check if graph has girth at least min_girth."""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (current, parent, depth)
        while queue:
            node, parent, depth = queue.pop(0)
            if depth >= min_girth:
                continue
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    # Found a cycle
                    cycle_len = depth + 1 + visited[neighbor]
                    if cycle_len < min_girth:
                        return False
                else:
                    visited[neighbor] = depth + 1
                    queue.append((neighbor, node, depth + 1))
    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

